package v1_test

import (
	"os"
	"path/filepath"
	"testing"

	"github.com/stretchr/testify/require"
	"sigs.k8s.io/yaml"

	"ocm.software/open-component-model/bindings/go/descriptor/normalisation"
	v1 "ocm.software/open-component-model/bindings/go/descriptor/normalisation/json/v1"
	descruntime "ocm.software/open-component-model/bindings/go/descriptor/runtime"
	v2 "ocm.software/open-component-model/bindings/go/descriptor/v2"
)

// ccutilsCases holds descriptors whose expected.json was generated by running
// gardener/cc-utils ocm/sign.py unchanged (see .review/pr-3887/ccutils-oracle).
const ccutilsCases = "../../../../../../.review/pr-3887/ccutils-oracle/cases"

// TestReviewPR3887_CCUtilsOracle asserts byte equality with real cc-utils
// output, the oracle the PR declares for jsonNormalisation/v1.
func TestReviewPR3887_CCUtilsOracle(t *testing.T) {
	cases, err := os.ReadDir(ccutilsCases)
	require.NoError(t, err)
	for _, c := range cases {
		t.Run(c.Name(), func(t *testing.T) {
			r := require.New(t)
			in, err := os.ReadFile(filepath.Join(ccutilsCases, c.Name(), "input.yaml"))
			r.NoError(err)
			expected, err := os.ReadFile(filepath.Join(ccutilsCases, c.Name(), "expected.json"))
			r.NoError(err)

			var desc v2.Descriptor
			r.NoError(yaml.Unmarshal(in, &desc))
			rt, err := descruntime.ConvertFromV2(&desc)
			r.NoError(err)

			got, err := normalisation.Normalise(rt, v1.Algorithm)
			r.NoError(err)
			r.Equal(string(expected), string(got), "normalised bytes diverge from cc-utils ocm/sign.py")
		})
	}
}
